ProjectALife.DialogueShards["replies_ask_16"] = {
{"ASK_MILITARY","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly,neutral",{"They set up at the high school and left again - we watched them drive away","I don't know, they were supposed to come, my husband waits for them every morning"}},
{"ASK_MILITARY","role=family_elder|tmp=seasoned|st=friendly,neutral|world=cars",{"Boys in trucks went through two days ago, never stopped to say a word"}},
{"ASK_MILITARY","role=family_elder|tmp=seasoned|st=friendly,neutral",{"In my day, the Army came when you called - not anymore"}},
{"ASK_MILITARY","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral|world=road",{"The Guard set up a roadblock, then they left - left all their gear in the road"}},
{"ASK_MILITARY","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral",{"I saw helicopters Friday - nothing since"}},
{"ASK_MILITARY","role=civilian_loner|tmp=seasoned|st=friendly,neutral",{"Saw a convoy heading north, never saw it come back"}},
{"ASK_MILITARY","role=worker|tmp=seasoned|st=friendly,neutral|world=cars",{"Trucks rolled past the plant Sunday, they didn't wave"}},
{"ASK_MILITARY","role=worker|tmp=seasoned|st=friendly,neutral",{"Soldiers at the interstate told us to turn around, then they were gone"}},
{"ASK_MILITARY","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral",{"National Guard came to the station, took our trucks - haven't seen them since"}},
{"ASK_MILITARY","role=rescue_medical|tmp=seasoned|st=friendly,neutral",{"A major told us they'd send supplies, that was the sixth, I'm still waiting"}},
{"ASK_MILITARY","role=rescue_clergy|tmp=seasoned|st=friendly,neutral",{"They blessed the cordon and then sealed it, I don't understand what was blessed"}},
{"ASK_MILITARY","role=law_deputy,law_officer|tmp=seasoned|st=friendly,neutral",{"Guard unit came through Saturday, told us to hold - then they went east","Dispatch says they're regrouping at Fort Knox, that's all I know"}},
{"ASK_MILITARY","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral|world=vehicle",{"They promised support, I got a single truck with two cases of MREs"}},
{"ASK_MILITARY","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral",{"A colonel told me the situation was contained, that was Saturday - look around"}},
{"ASK_MILITARY","role=law_trooper|tmp=veteran|st=friendly,neutral",{"I saw their checkpoint on the interstate, they told us to turn around or be arrested"}},
{"ASK_MILITARY","role=law_trooper|tmp=veteran|st=careful",{"Don't ask about the military"}},
{"ASK_MILITARY","role=law_corrections|tmp=seasoned|st=friendly,neutral",{"Guard unit reinforced the prison for two days, then they left, and so did my faith"}},
{"ASK_MILITARY","role=swat_lead,swat_operator|tmp=veteran|st=friendly,neutral",{"We tried coordinating with them, they sent a lieutenant and a map, that was it"}},
{"ASK_MILITARY","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral",{"I'm not allowed to talk about unit movements","Command hasn't updated us in days, maybe they've forgotten"}},
{"ASK_MILITARY","role=soldier_nco|tmp=veteran|st=friendly,neutral",{"We've lost contact with battalion, that's all I can say","Half the unit walked away, the other half is me"}},
{"ASK_MILITARY","role=deserter,militia|tmp=seasoned|st=friendly,neutral",{"The Army's gone, or it's busy shooting people - same thing","They'll tell you they're here to help, they're here to hold a line, not the same"}},
{"ASK_MILITARY","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly,neutral",{"They're stretched thin - that's all"}},
{"ASK_MILITARY","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=careful",{"No"}},
{"ASK_MILITARY","role=outlaw|tmp=seasoned|st=friendly,neutral",{"Soldiers shoot on sight at the checkpoints - be careful","Never trusted the Army - never will"}},
{"ASK_MILITARY","role=raider,raider_boss|tmp=predator|st=friendly,neutral",{"Army's busy, their loss is our gain"}},
{"ASK_MILITARY","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral",{"Soldiers got guns and orders, we got numbers and nothing to lose"}},
{"ASK_MILITARY","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral",{"Hit a roadblock outside Radcliff, turned around fast"}},
{"ASK_MILITARY","role=crime_member|tmp=seasoned|st=friendly,neutral",{"The government has other concerns, so do I"}},
{"ASK_MILITARY","role=prisoner|tmp=predator|st=friendly,neutral",{"The guard towers were empty when we left, that should tell you something"}},
{"ASK_MILITARY","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral|day=0,3",{"The Guard is coming, they have to be coming, it's their job, it's literally their job","They set up a line on the highway... I saw the trucks, I saw the guys in green, they're going to fix this","Maybe they're regrouping... maybe they're planning -- I tell myself that every night","They closed the roads, that's what I know, so they KNOW, so somebody's doing SOMETHING"}},
{"ASK_MILITARY","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral|day=4,14",{"They stopped answering, the line went quiet, and I think they ran, I think they just- ran","I saw a convoy go north... and it never came back, and I don't know what that means, do you?","They told us to stay put -- so we stayed, and now there's nobody left to tell us anything else","Maybe they're waiting for orders, maybe the orders never came, maybe they're dead"}},
{"ASK_MILITARY","role=civilian_man,civilian_woman|tmp=seasoned|st=friendly,neutral",{"Gone, I'd say, gone or dead, there hasn't been a soldier on the road in weeks","Heard they pulled out the same day it got bad, left their equipment behind, even some of their dead","If they were coming, they'd be here, so stop hoping, I stopped, it helps","I saw a helicopter once, high, heading away, never saw another","The army left us the same way it left Louisville, with a handshake and a lie"}},
{"ASK_MILITARY","role=civilian_man,civilian_woman|st=friendly",{"I hope they come, I do, and when they do, I'll be the first to buy them a drink","Waiting on them, same as you, and I hate every minute of it"}},
{"ASK_MILITARY","role=civilian_man,civilian_woman|st=careful",{"Don't talk to me about the army","Why do you ask? you one of them?","They left us, and I don't forgive that"}},
{"ASK_MILITARY","role=civilian_loner",{"Army's like weather, it comes or it doesn't, I don't plan around either","Seen 'em at the bridge, seen 'em pull out, seen 'em shoot at their own, I steer clear","Soldiers are men, men get scared, scared men with guns are the worst thing out here","Heard a few stayed behind, set up shop at the base, I wouldn't go near","Not my fight, never was"}},
{"ASK_MILITARY","role=family_man,family_woman,family_elder,family_youth|st=friendly,neutral",{"We keep hoping, the kids ask every morning, \"are the soldiers here yet?\" and I say soon, and I feel like a liar","My brother's in the Guard, he's out there somewhere, and I don't want to think about what he's seen","The army told us to evacuate, and then the army blocked the road, tell me how that makes sense"}},
{"ASK_MILITARY","role=family_elder",{"My boy was in the Gulf, honey, I know soldiers, and they would've come if they could","They'd never leave their own, never, so if they're not here, something worse than this happened","I served in Korea, nursing, and I know what a retreat looks like, this was a retreat"}},
{"ASK_MILITARY","role=family_youth",{"I mean, they're the Army, they have tanks and stuff, right? why aren't there tanks?","My cousin's in the National Guard, he called me, before the phones went out, said they were pulling back","Soldiers shot at a car full of people at the checkpoint, I saw it from the hill, so, like, I'm not sure I want them"}},
{"ASK_MILITARY","role=worker",{"They're saving their own skin, same as everybody, who can blame 'em","Unit stopped at the plant, took our trucks, said it was for the war effort, and left us with nothing","Guard wouldn't let us through the line, called us contaminated, I'm not contaminated, I'm tired"}},
{"ASK_MILITARY","role=rescue_medical",{"I treated a soldier who'd been shot by his own sergeant for trying to desert... so I don't trust the ones who stayed","They need medics worse than they need rifles, and none of them thought to bring any","The Army's got a protocol for everything, but this wasn't in the manual"}},
{"ASK_MILITARY","role=rescue_clergy",{"They're just boys in uniforms, scared ones, and I pray for every one, even the ones who frighten me","A boy in uniform came to the church for confession, three days ago, he was nineteen, and his hands wouldn't stop shaking"}},
{"ASK_MILITARY","role=rescue_firefighter",{"They commandeered our trucks on day two, and promised to return them, I'm still waiting","Their medics and ours worked side by side for a day, then they left without a word"}},
{"ASK_MILITARY","role=militia",{"We're what's left, the locals, the volunteers, we hold the line because the real line is gone","Active duty pulled out, no orders, no relief, I heard a few officers shot themselves instead of going back","If you see a soldier, treat him like a rattlesnake, he's scared, he's armed, and he's got nowhere to go"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best",{"I can tell you what I know, which isn't pretty, but you deserve to hear it from someone who's not lying!!","Far as I can tell they've left the whole county, I'm sorry","I'd trust you with this: I think they abandoned us, and I think it was a decision","They're not coming, friend, and I wish I had better news, but I won't lie!!","Last I saw, a convoy headed north, with the headlights off, and not one soldier waved","I know a man who was on the line, he says they got orders to hold, then orders to leave!!","Maybe some of them are still out there, doing right, some of them were decent","I talked to a private once, scared, young, he wanted to go home as badly as I do!","The Guard set up a perimeter, then folded it up in the night, and nobody left a note","Honestly? I think they're as lost as we are","There are a few left, scattered, guarding something, but I don't know what","I wouldn't count on them, but I wouldn't count them out, either","They used to wave at us from the trucks, those boys, now there's nothing","I heard they quarantined the whole county, and then forgot to let us know!","A sergeant told me once, \"we're doing all we can,\" and I believed him","They came, they went, they left behind a lot of empty promises","I hope some of them make it home, I do, they're someone's kids!","It's hard to say, it's hard to know, I try not to hate them","Rumor is they've gathered at the base, waiting for orders that never come","Whatever they were supposed to do, they didn't, and we paid for it","I saw one crying in a doorway, rifle on the floor, and I didn't know what to say!!","You'd think they'd have a plan, a map, a rescue, but, no","We shared water with a squad once -- they were kind, and then they vanished!","The military's like the weather, you can't count on it","I pray for them, even though they didn't pray for us","There's good and bad in every uniform","They're out there, I believe that, somewhere, doing something","It's a mystery, and I don't like mysteries","All I know is the hum of engines has stopped","I'd salute them, if I could find one","The last one I met told me to keep my head down, and he was right","They're as scared as we are, I'm sure of it"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=bad,worst",{"Why should I tell you anything about the army? you're not on my side"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=careful|rep=bad,worst",{"Get out of here"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral|mood=fear",{"Please don't say they're gone, please, they have to be coming, they HAVE to be","I saw them leave, I saw the trucks go, I stood in the road and waved like an idiot","They shot at us, at the barrier, they shot first and asked nothing, I'm scared of them now","The army? I don't know, I don't know, I just want somebody, ANYBODY, to take charge"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|mood=grim",{"Gone, I'd say, gone or dead or hiding, either way, they're not coming","The army knows how to win wars, not how to fix this, and they're out of their depth","Last I saw them, they were burning something in a pit, I turned and walked away","Don't count on them, count on whoever's standing next to you"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"My son's in the Guard, I don't know where, I don't know if... I don't know","There was a boy in a uniform... he couldn't have been twenty... he cried when he told us to turn back"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"The army ABANDONED us, I will say it to anyone, I'll say it to their faces","They locked the roads -- they locked us in, and then they left, and I will never forgive that","Soldiers -- my ass, they ran at the first sign of trouble, and called it a strategic retreat!"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"I like to think some of them are still out there, helping, saving, doing right","I've met a few decent soldiers -- they gave my daughter a candy bar, I haven't forgotten"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"The army? Oh, they're on a very long coffee break, a very, very long one","They said they'd be here in an hour, they're only a week late, give 'em time","The Army? They're on lunch break","Every time I see a soldier... I salute"},false,false,{[3]={{t="it's been a long lunch",afterMs=3000}},[4]={{t="mostly to make myself feel better",afterMs=3200}}}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=careful|mood=fear",{"I don't trust soldiers, I don't trust you, and I don't trust the news","Soldiers? They shoot first, I'd STAY clear!"}},
{"ASK_MILITARY","role=rescue_medical|st=friendly,neutral",{"The Guard brought us three soldiers with bites, said \"treat them,\" and then they never came back","They took our supply truck on day two, said it was for the cause, I'm still waiting for the cause","A medic from the Army stood next to me for an hour, then got a call, and left, and I haven't seen him","Their field hospital is a rumor, I've heard it a hundred times, never met a patient who'd seen it"}},
{"ASK_MILITARY","role=rescue_medical|st=careful",{"I don't discuss who I've treated, or which uniform they wore"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad,worst",{"The army would arrest you on sight, I bet","Why would I tell you anything about soldiers?","Ask them yourself, if you can find one that doesn't shoot you!","Soldiers have NO use for people like you","They'd love to meet you, I'm sure","Not telling you","They're not on your side, I assure you","You want to know about soldiers? Ask your victims!","Not your concern","You can't HIDE from them forever!","Don't mention the military to me!","If the Army knew what you'd done -- they'd come running!","That's classified, and I won't be sharing it with you","The army can't help you -- and neither can I!","I wouldn't tell you where they are if I knew","Go ask a soldier -- and see how it goes","They're not coming for you, and that's a shame","Believe me, they have standards","Why? are you running from them?","Soldiers? Gone... good riddance to everybody","I'd rather you didn't find them","Don't look to me for introductions","Stay off the roads where they patrol!","You and the army would not get along","They aren't your friends, and neither am I","Keep it to yourself, and keep your questions to yourself","Mind your own beeswax","Find a recruiter, and ask him","Forget the army, nobody is coming for you","I won't talk about them with you","You make me nervous, so, NO"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"Where's the army when you need them, right? RIGHT NOW?","They're not coming, look, look at what's here","The army? Pfft, there's no army, there's us","If the army were here... they'd be shooting by now","N-no time, no time, defend yourself!!"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"You look like army, with that, are you? you could be"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral",{"I saw them leave","A soldier gave me a bottle of water at a checkpoint","They're not coming","Half of them are just kids","They told us to wait","I heard they closed the whole county","There was a helicopter","A sergeant told me, \"Ma'am, go home\"","They shot at a car at the roadblock","The Army's got a plan","The Guard used to march in parades","I think most of them are dead","They're out there... somewhere -- I'm sure of it","My nephew's in the Guard"},false,false,{[1]={{t="a line of trucks, headlights off, no one waved",afterMs=3500},{t="I stood in the road like a fool",afterMs=3000}},[2]={{t="he couldn't look at me",afterMs=3500},{t="I think he was ashamed",afterMs=3000}},[3]={{t="I decided that on Tuesday",afterMs=3500},{t="I feel lighter since",afterMs=3000}},[4]={{t="I saw one cry at a barricade",afterMs=3200},{t="I wanted to hug him",afterMs=3000}},[5]={{t="we waited",afterMs=3200},{t="the waiting is over",afterMs=2800}},[6]={{t="like a fist",afterMs=3500},{t="and we're inside",afterMs=3000}},[7]={{t="it circled once",afterMs=3200},{t="and it went away",afterMs=2800}},[8]={{t="I said, \"I'm trying\"",afterMs=3500},{t="he looked away",afterMs=3000}},[9]={{t="I wasn't there, but I heard it",afterMs=3500},{t="I'll never forget the sound",afterMs=3000}},[10]={{t="and we're not in it",afterMs=3200}},[11]={{t="I waved at them",afterMs=3500},{t="I feel foolish now",afterMs=3000}},[12]={{t="or deserted",afterMs=3200},{t="I can't blame the second kind",afterMs=2800}},[13]={{t="and I hope they're looking for us",afterMs=3500}},[14]={{t="I don't know where",afterMs=3500},{t="I write him letters",afterMs=3000},{t="I don't mail them",afterMs=2800}}}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly",{"I like to think they'll come back for us"},false,false,{[1]={{t="wouldn't you?",afterMs=3200}}}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=careful",{"I'm not discussing the military","Soldiers aren't my friends","Soldiers shoot first","Ask them yourself","Gone","Why are you asking about the Army? You one of them? Keep your hands out where I can see them"},false,false,{[3]={{t="I'd rather not discuss them",afterMs=3000}},[4]={{t="if you can find any",afterMs=3000}},[5]={{t="good riddance",afterMs=3000}}}},
{"ASK_MILITARY","role=civilian_loner|st=friendly,neutral",{"They came through in trucks, then they went through the other way","I stay out of the army's business","Soldiers walk loud and shoot quick","Saw a helicopter"},false,false,{[1]={{t="faster",afterMs=3500}},[2]={{t="and out of the army's sight",afterMs=3200}},[3]={{t="I don't care for either",afterMs=3500}},[4]={{t="it didn't see me",afterMs=3200},{t="good",afterMs=2800}}}},
{"ASK_MILITARY","role=civilian_loner|st=careful",{"Soldiers aren't my concern, and neither are you"}},
{"ASK_MILITARY","role=family_elder|st=friendly,neutral",{"I served in the war, I'll have you know, nursing","Soldiers are boys... dear, and boys get frightened...","They set up a camp near the church"},false,false,{[1]={{t="I know what a retreat looks like",afterMs=3500},{t="I saw it here",afterMs=3000}},[2]={{t="I don't blame them",afterMs=3200}},[3]={{t="then they left in the night",afterMs=3500},{t="the sergeant wouldn't meet my eye",afterMs=3000}}}},
{"ASK_MILITARY","role=family_elder|st=careful",{"I don't talk about soldiers"}},
{"ASK_MILITARY","role=family_youth|st=friendly,neutral",{"Okay, so, my cousin's in the Guard, and he said they got orders to leave","They have tanks and stuff","The soldiers at the checkpoint were super scared"},false,false,{[1]={{t="he cried when he told me",afterMs=3500}},[2]={{t="where are the tanks??",afterMs=3200},{t="that's what I want to know",afterMs=2800}},[3]={{t="like, as scared as us",afterMs=3500}}}},
{"ASK_MILITARY","role=family_youth|st=careful",{"Soldiers? Don't know any"}},
{"ASK_MILITARY","role=worker|st=friendly,neutral",{"The Guard closed the plant gate and put a soldier on it","I drove a delivery truck for the Army once..","They took our fuel on the third day"},false,false,{[1]={{t="he was nineteen, tops",afterMs=3500},{t="he cried when I tried to go home",afterMs=3000}},[2]={{t="they're organized, I'll say that",afterMs=3200},{t="until it counts",afterMs=2800}},[3]={{t="said they'd pay later",afterMs=3500},{t="later never came",afterMs=3000}}}},
{"ASK_MILITARY","role=worker|st=careful",{"Don't ask me about soldiers"}},
{"ASK_MILITARY","role=family_man,family_woman|st=friendly,neutral",{"A soldier let us through a barricade with the kids in the back","They told us to wait for evacuation"},false,false,{[1]={{t="I'll never forget his face",afterMs=3500}},[2]={{t="the buses never came",afterMs=3200},{t="we're still waiting",afterMs=2800}}}},
{"ASK_MILITARY","role=family_man,family_woman|st=careful",{"Soldiers don't help families"}},
{"ASK_MILITARY","role=rescue_clergy|st=friendly,neutral",{"I counsel the soldiers, when they come..","A lieutenant sat in my pew and wept"},false,false,{[1]={{t="they're terrified boys... mostly",afterMs=3500},{t="terrified and ashamed",afterMs=3000}},[2]={{t="he'd left his men",afterMs=3200}}}},
{"ASK_MILITARY","role=rescue_clergy|st=careful",{"I pray for them, as I pray for you!!"}},
{"ASK_MILITARY","role=rescue_firefighter|st=friendly,neutral",{"We worked beside the Guard on the second day","They took our hoses, said they'd return them"},false,false,{[1]={{t="good folks, scared folks",afterMs=3500},{t="then they were gone",afterMs=3000}},[2]={{t="I wouldn't hold my breath",afterMs=3200}}}},
{"ASK_MILITARY","role=rescue_firefighter|st=careful",{"Soldiers are soldiers"}},
{"ASK_MILITARY","role=militia|st=friendly,neutral",{"I'm not Army... friend","They gave us radios and a phone number"},false,false,{[1]={{t="I'm a neighbor with a rifle",afterMs=3500},{t="there's a difference",afterMs=3000}},[2]={{t="neither works",afterMs=3200}}}},
{"ASK_MILITARY","role=militia|st=careful",{"Don't ask about the Army"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,3",{"They'll be here any minute, I'm sure of it, any minute now","The Guard was on the highway yesterday, I saw the trucks","They said help is coming"},false,false,{[3]={{t="I'm choosing to believe that",afterMs=3500}}}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|day=4,14",{"A week and no sign of them","They stopped coming past the checkpoint, I guess they're regrouping"},false,false,{[1]={{t="I'm starting to worry",afterMs=3500}},[2]={{t="I keep saying that to myself",afterMs=3200}}}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=friendly,neutral|day=15,99999",{"They're not coming, we all know it","The army's gone","After all this time, I don't even hope anymore"},false,false,{[1]={{t="nobody says it, but we know",afterMs=3500}},[2]={{t="if they were here, we'd see them",afterMs=3200}}}},
{"ASK_MILITARY","reg=raider|st=neutral,careful",{"The Army? They sealed the county and left us in here, so no, I'm not holding my breath","A soldier shot a neighbor of mine and the guy wasn't even sick, so don't ask me for a good word about them","They're out there, sure, parked at the line, but they sure as hell aren't coming to help","The Army has its own mess to clean up, we're just the leftovers","I saw a convoy rolling north on the second day, packed with gear, no stopping, no waving, nothing","Soldiers are the only ones with bigger guns than me, so I stay out of their way and they stay out of mine","Boys in uniform stand at the roadblocks and shoot anybody who looks sick, and half the time they're wrong","They'll be back to clean up when it's convenient for them, and I'll be long gone by then"}},
{"ASK_MILITARY","reg=raider|st=hostile",{"You want the Army? Wave at them from the ground","You with them? You better not be, because I got something special for soldiers"}},
{"ASK_MILITARY","reg=raider|st=friendly",{"I keep hoping a convoy rolls in with food and medicine, you know? Dumb, but I keep hoping","Honestly I'd turn myself over to the Army in a second if they promised me a bed and a hot meal"}},
{"ASK_MILITARY","reg=gang|st=neutral,careful",{"Army's at the checkpoints, shooting anybody who looks sick -- that's what I heard, anyway","They sealed the roads and bounced, that's the Army for you","Man, the Guard came through our neighborhood on day two, kicked in doors, took whatever they wanted","My cousin's in the Guard, ain't heard from him since Friday, I'm real worried","They don't care about us, they protect the rich side of Louisville first"}},
{"ASK_MILITARY","reg=gang|st=hostile",{"Army can kiss my ass, they're no help to anybody"}},
{"ASK_MILITARY","reg=gang|st=friendly",{"I heard they're setting up a camp up north, maybe that's good news, maybe it's a trap, I don't know"}},
{"ASK_MILITARY","reg=club|st=neutral,careful",{"They came through two days ago, shot at us, then left, so no, I don't trust 'em","Saw a whole squad driving the wrong direction, away from the base, nobody looked happy","Don't trust them, they're protecting themselves, not us","I did four years in the service, so I know exactly how little they care about civilians"}},
{"ASK_MILITARY","reg=club|st=hostile",{"Army's the enemy, and so are you if you're with them"}},
{"ASK_MILITARY","reg=club|st=friendly",{"I hear they've got a field hospital at the base, might be worth checking out, {g:brother|sister}"}},
{"ASK_MILITARY","reg=crime|st=neutral,careful",{"The military are following orders, none of which benefit us","They are inconsistent, to put it mildly, one day a checkpoint, the next day nothing","I do business with soldiers when I can, they are always more reasonable than their officers","They want the county sealed, but I notice they don't want to come inside and see why"}},
{"ASK_MILITARY","reg=crime|st=friendly",{"I wish I knew what they were planning, for all our sakes"}},
{"ASK_MILITARY","reg=prison|st=neutral,careful",{"Army came to the prison, took some guards, left the rest of us locked in until the dead broke the doors","They shot at us when we ran, I'm not going near them ever again","Soldiers don't care who you are, convict or not, they'll shoot first"}},
{"ASK_MILITARY","reg=prison|st=hostile",{"Army, cops, they're all the same! They'd send me right back!"}},
{"ASK_MILITARY","reg=prison|st=friendly",{"If they offered me food I'd probably surrender, honestly"}},
{"ASK_MILITARY","reg=outlaw|st=neutral,careful",{"They set up roadblocks, then abandoned them, I don't know what to think","Saw a convoy the other day, kept going, didn't stop for anybody","Fort Knox is right there, how do they not know what's going on? Or do they?","I figure the Army is waiting for us all to die so they can clean it up quietly"}},
{"ASK_MILITARY","reg=outlaw|st=friendly",{"They'll come, friend, they always do eventually, it's just a matter of how long we hold on"}},
{"ASK_MILITARY","role=deserter|st=neutral,careful",{"I can't-- I just can't talk about that, please","They told us to keep civilians in, not to let anyone out, I didn't like it"}},
{"ASK_MILITARY","role=deserter|st=hostile",{"Leave the Army out of this, you hear me? I'll shoot you if you tell them I'm here!"}},
{"ASK_MILITARY","reg=law|st=neutral,careful",{"We've had limited contact with the Guard, nothing official","They're deployed in the county, but they haven't coordinated with us","The Army has the authority, but I haven't seen them use it","I called the base three times on the first night and got a recording, a recording, can you believe that"}},
{"ASK_MILITARY","reg=law|st=hostile",{"That's above both our pay grades"}},
{"ASK_MILITARY","reg=law|st=friendly",{"I hope they get here soon, we need all the help we can get"}},
{"ASK_MILITARY","role=law_sheriff|st=neutral,careful",{"I've asked Fort Knox for help three times and got nothing, not one answer"}},
{"ASK_MILITARY","reg=military|st=neutral,careful",{"We are the Army, and we're doing our best","I'm not authorized to speak about operational matters","Reinforcements are expected, but there's no timeline","Orders are to hold and contain, that's the full extent of what I know"}},
{"ASK_MILITARY","reg=military|st=hostile",{"Questions about the military are not welcome"}},
{"ASK_MILITARY","reg=military|st=friendly",{"We're trying to help, we really are, there's just so much to do and not enough of us"}},
{"ASK_MILITARY","role=soldier_nco|st=neutral,careful",{"The Army will get us out, give it time","Anybody tells you the Army has abandoned you is lying, and I'll put them on a charge"}},
{"ASK_MILITARY","role=soldier_green|st=neutral,careful",{"I don't know, honestly, nobody tells us anything, we just do what we're told... please don't ask me more","Half my squad is gone, I don't even know who's in charge anymore"}},
{"ASK_MILITARY","reg=elite|st=neutral,careful",{"There are people above this you don't want to meet"}},
{"ASK_MILITARY","role=mercenary|st=neutral,careful",{"The Army pays slow, I prefer cash"}},
{"ASK_MILITARY","role=militia|st=neutral,careful",{"We saw them pull out on the second day, left their trucks and everything","Army ain't coming, and I don't blame them, it's bigger than anyone","Last thing the Army told us was to stay inside, so we stayed inside, and look where it got us"}},
{"ASK_MILITARY","role=militia|st=friendly",{"We keep watching the road, hoping for good news"}},
{"ASK_MILITARY","reg=civilian,family|tmp=fresh|st=friendly,neutral|day=0,7",{"They're coming, my cousin saw trucks on 31W headed north, a whole line of them - they're coming, right?","Soldiers at the roadblock told us to go home and wait - so I'm waiting, I'm just waiting out here instead"},false,{[1]="GENERIC"}},
{"ASK_MILITARY","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=building",{"I waved at a helicopter for twenty minutes yesterday, it went right on by, like I was a mailbox"}},
{"ASK_MILITARY","reg=civilian,family|st=friendly,neutral|day=8,9999",{"Army's out there somewhere, they're just not out here - I made my peace with that last week"}},
{"ASK_MILITARY","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|world=fence",{"The Army came and put up fences, and then pointed the guns at US, go figure"}},
{"ASK_MILITARY","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral|day=6,9999",{"Guard came in the first days, some of them are still around - just not standing up"}},
{"ASK_MILITARY","reg=civilian,family,worker,rescue|st=hostile",{"Army can come get you for all I care - keep walking"}},
{"ASK_MILITARY","reg=worker|st=friendly,neutral",{"Saw a convoy blow through the weigh station on 31W doing about eighty - no stopping, no waving - just gone","Drove parts out to Fort Knox for nine years, gate guards knew my name - last time I went up, they aimed at my truck"}},
{"ASK_MILITARY","reg=rescue|role=rescue_firefighter|st=friendly,neutral|world=generator",{"We asked the Guard for help at the station, they took our diesel and our generator, signed a paper for it, at least"}},
{"ASK_MILITARY","reg=rescue|role=rescue_medical,rescue_clergy|st=friendly,neutral",{"Army medics came through the clinic on day two and took our patient list - never said where the list was going"}},
{"ASK_MILITARY","reg=law,swat|st=friendly,neutral",{"Guard's supposed to be holding the perimeter, we lost contact with their liaison the third day"}},
{"ASK_MILITARY","reg=law|st=friendly,neutral",{"Soldiers took over our roadblock on 31W, real polite about it, then they turned the rifles on the people we'd been helping"}},
{"ASK_MILITARY","reg=law|role=law_trooper|st=friendly,neutral",{"State Police were told to coordinate with the Guard - we coordinated - they left, we didn't"}},
{"ASK_MILITARY","reg=law,swat|st=careful,hostile",{"The military isn't taking visitors and neither am I - back up"}},
{"ASK_MILITARY","reg=military|tmp=seasoned,veteran|st=friendly,neutral",{"We're around, not as many as you'd like, and not doing what you'd like"}},
{"ASK_MILITARY","reg=military|st=friendly,neutral|day=0,10",{"My orders are to hold the perimeter, not escort civilians - I'm sorry, that's the truth of it"}},
{"ASK_MILITARY","reg=military|st=friendly,neutral|day=8,9999",{"Last I heard, battalion pulled back toward post, I'm the part that didn't get pulled back"}},
{"ASK_MILITARY","reg=military|role=soldier_green|st=friendly,neutral",{"I've been in eight months, basic didn't cover anything like this, and nobody's told us a thing since"}},
{"ASK_MILITARY","reg=elite",{"Assets are committed, none of them are for you"}},
{"ASK_MILITARY","reg=military,elite|st=careful,hostile",{"You're looking at the military - stop right there"}},
{"ASK_MILITARY","reg=military|st=careful",{"That's close enough - keep your hands up and tell me where you came from"}},
{"ASK_MILITARY","reg=military|role=deserter",{"Army's who shot that family at the roadblock outside Muldraugh - so no, I'm not with them anymore"}},
{"ASK_MILITARY","reg=outlaw,raider,crime,prison|st=friendly,neutral|world=road",{"Soldier boys are the scariest thing in this county, and I'm counting the dead - stay off the highway"}},
{"ASK_MILITARY","reg=outlaw,raider|st=friendly,neutral",{"Took a rifle off a Guardsman on 31W, he didn't need it anymore, that's your military"}},
{"ASK_MILITARY","reg=gang,club|st=friendly,neutral",{"Army? They left their trucks on the shoulder with the keys in 'em - that's how bad they want to come back"}},
{"ASK_MILITARY","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"Army ain't coming for you, nobody's coming for you, that's the fun part"}},
{"ASK_MILITARY","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Military's busy - we're not"}},
{"ASK_MILITARY","reg=raider,prison,club|st=careful,hostile",{"See any soldiers around? Me neither - keep that in mind while you're standing there"}},
{"ASK_MILITARY","role=deserter|st=careful,neutral",{"You want what I saw at the line? It ain't the official version of it","They're doing what they were told, that's the frightening part, not the opposite"},false,{[1]="ASK_MILITARY"}},
{"ASK_MILITARY","role=deserter,soldier_green|st=careful,neutral",{"I stood a roadblock till the eighth - you want to hear why I ain't on it now?"},false,{[1]="ASK_MILITARY"}},
{"ASK_MILITARY","role=soldier_nco,elite_delta|tmp=veteran|st=neutral",{"Folks think they're coming back through here - you want my opinion on that?"},false,{[1]="ASK_MILITARY"}},
{"ASK_MILITARY","reg=civilian|tmp=fresh|st=friendly,neutral",{"They came through on the sixth with loudspeakers, then they went back the other way"}},
{"ASK_MILITARY","reg=family|st=neutral",{"Convoy went past our house twice, second time they wasn't stopping for anybody"}},
{"ASK_MILITARY","reg=worker|tmp=seasoned|st=neutral|world=road",{"They're on the roads, not in the towns, that's what I've seen with my own eyes"}},
{"ASK_MILITARY","role=rescue_firefighter|st=neutral",{"The Guard boys at the school were kids, scared kids with rifles, worst kind there is"}},
{"ASK_MILITARY","role=rescue_clergy|st=neutral|mood=sad",{"A soldier asked me to pray with him at the roadblock - nineteen, maybe twenty"}},
{"ASK_MILITARY","role=law_deputy|st=neutral",{"They don't coordinate with us, they've got their own net and we ain't on it"}},
{"ASK_MILITARY","role=soldier_nco|tmp=veteran|st=neutral",{"You want my honest read on the Army right now? Think before you answer that"}},
{"ASK_MILITARY","role=soldier_green|tmp=fresh|st=neutral|mood=fear",{"Half our platoon didn't come back off a sweep on the eighth - nobody's said a word"}},
{"ASK_MILITARY","role=elite_delta|tmp=veteran|st=neutral",{"Regular units are built to hold a line, lines don't work against this, that's the problem in a nutshell"}},
{"ASK_MILITARY","reg=club|st=neutral",{"Saw a column on 31W doing about fifty, buttoned up, not stopping for a soul"}},
{"ASK_MILITARY","reg=raider,gang|tmp=predator|st=hostile|world=inside",{"The Army's the best fence I ever had, keeps everybody in here with me"}},
{"ASK_MILITARY","reg=civilian,family|tmp=fresh|st=hostile|mood=angry",{"The Army's why we can't leave! Don't you talk to me about the Army!"}},
}
